const square = (n) => {
  console.log("compute");
  return n * n;
};
const memo = (fn) => {
  const cache = new Map();
  return (n) => {
    if (cache.has(n)) return cache.get(n);
    const result = fn(n);
    cache.set(n, result);
    return result;
  };
};
const fast = memo(square);
console.log(fast(9));
console.log(fast(9));
console.log(fast(4));

let calls = 0;
const fib = (n) => {
  calls++;
  return n < 2 ? n : fib(n - 1) + fib(n - 2);
};
console.log(fib(20), calls);

let calls = 0;
const cache = new Map();
const fib = (n) => {
  if (cache.has(n)) return cache.get(n);
  calls++;
  const r = n < 2 ? n : fib(n - 1) + fib(n - 2);
  cache.set(n, r);
  return r;
};
console.log(fib(20), calls);
